html:
{#
  Macros
  fix_lig: reemplaza ligaturas Unicode (fi, fl, ff, ffi, ffl)
#}
{%- macro fix_lig(t) -%}{{ t | replace('ﬁ','fi') | replace('ﬂ','fl') | replace('ﬀ','ff') | replace('ﬃ','ffi') | replace('ﬄ','ffl') }}{%- endmacro -%}

{%- set company = frappe.get_doc('Company', doc.company) if doc.company else None -%}
{%- set owner_name = frappe.db.get_value('User', doc.owner, 'full_name') if doc.owner else '' -%}
{%- set owner_email = frappe.db.get_value('User', doc.owner, 'email') if doc.owner else '' -%}
{%- set scope_rows = doc.quotation_scope_items | selectattr('include_in_proposal') | list -%}
{%- set has_designation = scope_rows | selectattr('designation') | list | length > 0 -%}
{%- set has_activity = scope_rows | selectattr('activity_type') | list | length > 0 -%}
{%- set total_est_h = namespace(v=0.0) -%}
{%- for r in scope_rows %}{%- set total_est_h.v = total_est_h.v + (r.estimated_hours or 0) -%}{%- endfor -%}

{# ── Snapshot detection ─────────────────────────────────────── #}
{# Proposals frozen at Borrador→En Revision use snapshot.        #}
{# Draft proposals use the live template catalog.                #}
{%- set _raw_snap = doc.proposal_sections_snapshot -%}
{%- set _snap_list = parse_json(_raw_snap) if _raw_snap else [] -%}
{%- set use_snapshot = _snap_list | length > 0 -%}
{%- set _frozen_states = ["En Revision", "Aprobada", "Rechazada", "Enviada al Cliente"] -%}
{%- set _is_frozen = doc.workflow_state in _frozen_states or doc.docstatus == 1 -%}

{%- if use_snapshot -%}
  {# ── Snapshot path: split by is_executive_summary ──────────── #}
  {%- set snap_exec = _snap_list | selectattr('is_executive_summary') | list -%}
  {%- set snap_body = _snap_list | rejectattr('is_executive_summary') | list -%}
{%- else -%}
  {# ── Live path: read from template catalog ──────────────────── #}
  {%- set _tmpl_obj = frappe.get_doc('Proposal Template', doc.proposal_template) if doc.proposal_template else None -%}
  {%- set exec_sections  = [] -%}
  {%- set body_sections  = [] -%}
  {%- set late_sections  = [] -%}
  {%- if _tmpl_obj -%}
    {%- for row in _tmpl_obj.sections | sort(attribute='sequence') -%}
      {%- set _ps = frappe.get_doc('Proposal Section', row.proposal_section) -%}
      {%- if (row.sequence or 0) >= 500 -%}
        {%- set _ = late_sections.append(row) -%}
      {%- elif _ps.is_executive_summary -%}
        {%- set _ = exec_sections.append(row) -%}
      {%- else -%}
        {%- set _ = body_sections.append(row) -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endif -%}

<style>
  :root {
    /* Marca */
    --color-primary:        #2563eb;   /* azul — acento principal */
    --color-primary-dark:   #1a1a2e;   /* navy — headers, fondos oscuros */
    --color-secondary:      #4a5568;   /* gris-azul — TOC, secciones legales */
    --color-muted:          #64748b;   /* gris medio — etiquetas */

    /* Fondos */
    --color-bg-highlight:   #f0f4ff;   /* azul suave — bloque cliente, exec summary */
    --color-bg-soft:        #f8f9fc;   /* gris muy suave — filas alternas, notas */
    --color-bg-stripe:      #e8edf8;   /* franja — encabezados de tabla, phase rows */
    --color-bg-subtle:      #f4f6fb;   /* sutil — totales de fase */

    /* Bordes */
    --color-border:         #c7d4f0;   /* borde tarjetas */
    --color-border-muted:   #94a3b8;   /* borde bloque emisor */

    /* Texto */
    --color-text:           #333;
    --color-text-secondary: #555;
    --color-text-muted:     #666;

    /* Texto sobre fondos oscuros */
    --color-on-primary:     #fff;       /* texto sobre primary-dark */

    /* Banner confidencial */
    --color-accent-bg:      #f0fdf4;
    --color-accent-border:  #86efac;
    --color-accent-text:    #14532d;   /* verde oscuro */
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, Helvetica, sans-serif; font-size: 10pt; color: #2c2c2c; }
  @page { margin: 1.5cm; }

  /* ── Portada ─────────────────────────────── */
  .cover { page-break-after: always; padding: 0 0 24px; position: relative; }
  .cover-band { height: 14px; background: linear-gradient(90deg, var(--color-primary-dark) 0%, var(--color-primary) 100%); }
  .cover-header { display: flex; justify-content: space-between; align-items: center; padding: 24px 0 20px; border-bottom: 1px solid #e0e4ed; margin-bottom: 32px; }
  .cover-logo-area { display: flex; align-items: center; }
  .cover-logo-area img { height: 140px; width: auto; object-fit: contain; display: block; }
  .company-name-fallback { font-size: 13pt; font-weight: bold; color: var(--color-primary-dark); letter-spacing: 0.3px; }
  .cover-badge { background: var(--color-primary-dark); color: #fff; font-size: 7.5pt; font-weight: bold; letter-spacing: 2px; text-transform: uppercase; padding: 7px 16px; border-radius: 2px; white-space: nowrap; }
  .cover-title-block { text-align: center; padding: 28px 0 32px; border-bottom: 2px solid #e0e4ed; margin-bottom: 36px; }
  .cover-main-title { font-size: 38pt; font-weight: bold; color: var(--color-primary-dark); line-height: 1.1; letter-spacing: -0.5px; margin-bottom: 10px; }
  .cover-subtitle { font-size: 13pt; color: var(--color-secondary); font-weight: normal; line-height: 1.4; }
  .cover-parties { display: grid; grid-template-columns: 1.4fr 1fr; gap: 28px; margin-bottom: 28px; }
  .cover-client { background: var(--color-bg-highlight); border-left: 5px solid var(--color-primary); padding: 20px 22px; }
  .cover-issuer { background: var(--color-bg-soft); border-left: 3px solid var(--color-border-muted); padding: 16px 18px; }
  .party-label { font-size: 7pt; font-weight: bold; text-transform: uppercase; letter-spacing: 1.2px; margin-bottom: 8px; }
  .cover-client .party-label { color: var(--color-primary); }
  .cover-issuer .party-label { color: var(--color-muted); }
  .client-name { font-size: 14pt; font-weight: bold; color: var(--color-primary-dark); line-height: 1.3; margin-bottom: 14px; }
  .issuer-name { font-size: 11pt; font-weight: bold; color: var(--color-primary-dark); margin-bottom: 6px; }
  .issuer-detail { font-size: 8.5pt; color: var(--color-muted); line-height: 1.6; }
  .cover-meta-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 16px; }
  .cover-meta-row { display: flex; align-items: baseline; gap: 6px; padding: 2px 0; font-size: 8.5pt; }
  .meta-key { color: var(--color-muted); font-weight: bold; text-transform: uppercase; font-size: 7pt; letter-spacing: 0.3px; min-width: 52px; }
  .meta-val { color: var(--color-primary-dark); font-weight: 500; }
  .confidential-banner { background: var(--color-accent-bg); border: 1px solid var(--color-accent-border); text-align: center; padding: 6px; font-size: 7.5pt; color: var(--color-accent-text); font-weight: bold; letter-spacing: 1px; margin-top: 4px; }

/* ── Resumen Ejecutivo ──────────────────────── */
  .exec-summary { background: var(--color-bg-highlight); border: 1px solid var(--color-border); border-top: 4px solid var(--color-primary); border-radius: 3px; padding: 28px 28px 24px; margin-bottom: 0; page-break-inside: avoid; page-break-after: always; }
  .exec-summary-title { font-size: 15pt; font-weight: bold; color: var(--color-primary-dark); letter-spacing: 0.5px; margin-bottom: 6px; }
  .exec-summary-subtitle { font-size: 8pt; font-weight: bold; color: var(--color-primary); text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 18px; padding-bottom: 12px; border-bottom: 1px solid var(--color-border); }
  .exec-content { font-size: 9.5pt; line-height: 1.7; color: var(--color-text); margin-bottom: 20px; }
  .exec-content p { margin-bottom: 6px; }
  .exec-content ul, .exec-content ol { padding-left: 18px; margin-bottom: 6px; }
  .exec-content li { margin-bottom: 3px; }
  .exec-data-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 4px; }
  .exec-card { background: #fff; border: 1px solid var(--color-border); border-radius: 2px; padding: 10px 14px; }
  .ec-label { font-size: 6.5pt; font-weight: bold; color: #6b7d99; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 4px; }
  .ec-value { font-size: 10pt; font-weight: bold; color: var(--color-primary-dark); }

  /* ── Índice ──────────────────────────────── */
  .toc-block { margin-bottom: 24px; }
  .toc-title { font-size: 11pt; font-weight: bold; color: #fff; background: var(--color-primary-dark); padding: 9px 14px; margin-bottom: 10px; letter-spacing: 0.3px; }
  .toc-list { list-style: none; padding: 0; columns: 2; column-gap: 24px; }
  .toc-list li { padding: 4px 0; border-bottom: 1px dotted #ddd; font-size: 9pt; color: var(--color-text); }
  .toc-num { display: inline-block; width: 18px; font-weight: bold; color: var(--color-primary); }

  /* ── Secciones narrativas ─────────────────── */
  .section { margin-bottom: 32px; }
  .section + .section { border-top: 1px solid var(--color-bg-stripe); padding-top: 6px; }
  h2.section-title { font-size: 11pt; font-weight: bold; color: #fff; background: var(--color-primary-dark); padding: 9px 14px; margin-bottom: 18px; letter-spacing: 0.3px; }
  .section-content { font-size: 9.5pt; line-height: 1.72; color: var(--color-text); }

  /* Párrafos y bloques */
  .section-content p { margin-bottom: 10px; }
  .section-content p:last-child { margin-bottom: 0; }
  .section-content p + ul, .section-content p + ol { margin-top: 2px; }
  .section-content table + p, .section-content ul + p, .section-content ol + p { margin-top: 12px; }

  /* Listas */
  .section-content ul, .section-content ol { padding-left: 22px; margin-bottom: 10px; margin-top: 4px; }
  .section-content li { margin-bottom: 5px; line-height: 1.65; }
  .section-content li:last-child { margin-bottom: 0; }
  .section-content ul ul, .section-content ol ul,
  .section-content ul ol, .section-content ol ol { margin-top: 4px; margin-bottom: 4px; padding-left: 18px; }

  /* Sub-encabezados */
  .section-content h3 { color: var(--color-primary-dark); margin: 16px 0 8px; font-size: 10.5pt; border-bottom: 1px solid var(--color-bg-stripe); padding-bottom: 4px; }
  .section-content h4 { color: var(--color-secondary); margin: 12px 0 5px; font-size: 10pt; font-weight: bold; }
  .section-content h5, .section-content h6 { color: var(--color-muted); margin: 10px 0 4px; font-size: 9.5pt; font-weight: bold; }

  /* Énfasis */
  .section-content strong, .section-content b { color: var(--color-primary-dark); }

  /* Blockquotes (contenido citado o pegado desde Word) */
  .section-content blockquote { border-left: 3px solid var(--color-border); padding: 8px 14px; margin: 10px 0; color: var(--color-text-secondary); font-style: italic; background: var(--color-bg-soft); }

  /* Código inline o bloques técnicos */
  .section-content code { background: var(--color-bg-soft); font-family: monospace; font-size: 8pt; padding: 1px 4px; border: 1px solid var(--color-border); }
  .section-content pre { background: var(--color-bg-soft); font-family: monospace; font-size: 8pt; padding: 10px 12px; margin: 8px 0; border-left: 3px solid var(--color-border); white-space: pre-wrap; word-break: break-all; }

  /* Tablas profesionales */
  .section-content table { width: 100%; border-collapse: collapse; margin: 12px 0 16px; font-size: 9pt; word-break: break-word; }
  .section-content table th { background: var(--color-bg-stripe); color: var(--color-primary-dark); padding: 7px 11px; text-align: left; border: 1px solid #ccd; font-weight: bold; font-size: 8.5pt; letter-spacing: 0.2px; }
  .section-content table td { padding: 7px 11px; border: 1px solid #dde; vertical-align: top; line-height: 1.55; }
  .section-content table tr:nth-child(even) td { background: var(--color-bg-soft); }
  .section-content table tr:hover td { background: var(--color-bg-highlight); }


  /* ── Plan de Trabajo ─────────────────────── */
  table.deploy-table { width: 100%; border-collapse: collapse; font-size: 8.5pt; margin-top: 2px; }
  table.deploy-table th { background: var(--color-primary-dark); color: #fff; padding: 6px 9px; text-align: left; font-size: 8pt; }
  table.deploy-table th.right, table.deploy-table td.right { text-align: right; }
  table.deploy-table td { padding: 5px 9px; border-bottom: 1px solid #eee; vertical-align: top; }
  tr.phase-row td { background: var(--color-bg-stripe); font-weight: bold; font-size: 9.5pt; color: var(--color-primary-dark); border-top: 3px solid var(--color-primary); padding: 7px 9px; }
  tr.phase-total td { background: var(--color-bg-subtle); font-style: italic; border-top: 1px solid #ccd; font-size: 8pt; }
  table.deploy-table tfoot td { background: var(--color-primary-dark); color: #fff; font-weight: bold; padding: 7px 9px; font-size: 9pt; }
  td.task-cell { padding-left: 20px; }
  .task-desc { font-size: 7.5pt; color: var(--color-text-muted); margin-top: 3px; line-height: 1.4; }

  /* ── Entregables ─────────────────────────── */
  .deliverable-item { margin-bottom: 12px; padding: 10px 14px; border-left: 3px solid var(--color-primary-dark); background: #fafbff; page-break-inside: avoid; }
  .deliverable-title { font-size: 9.5pt; font-weight: bold; color: var(--color-primary-dark); margin-bottom: 6px; }
  .deliverable-body { font-size: 8.5pt; color: var(--color-text); line-height: 1.55; }
  .deliverable-body p { margin-bottom: 4px; }
  .deliverable-body ul, .deliverable-body ol { padding-left: 16px; }

  /* ── Inversión ───────────────────────────── */
  table.items-table { width: 100%; border-collapse: collapse; font-size: 9pt; }
  table.items-table th { background: var(--color-primary-dark); color: var(--color-on-primary); padding: 8px 12px; text-align: left; font-size: 8.5pt; letter-spacing: 0.2px; }
  table.items-table th.right, table.items-table td.right { text-align: right; }
  table.items-table td { padding: 8px 12px; border-bottom: 1px solid #eee; vertical-align: top; }
  table.items-table tr:last-child td { border-bottom: none; }
  table.items-table tr:nth-child(even) td { background: var(--color-bg-soft); }
  .item-name { font-weight: 500; color: var(--color-text); }
  .item-desc { font-size: 8pt; color: var(--color-text-muted); margin-top: 3px; line-height: 1.4; }
  .totals-block { margin-top: 18px; }
  .totals-subtotals { display: flex; justify-content: flex-end; margin-bottom: 6px; }
  .totals-inner { width: 44%; }
  .totals-row { display: flex; justify-content: space-between; padding: 5px 12px; font-size: 9pt; color: var(--color-text); border-bottom: 1px solid #f0f0f0; background: var(--color-bg-soft); }
  .totals-grand { display: flex; justify-content: space-between; align-items: center; background: var(--color-primary-dark); color: var(--color-on-primary); padding: 12px 16px; margin-top: 2px; }
  .totals-grand span { color: var(--color-on-primary); }
  .grand-label { font-size: 9.5pt; font-weight: bold; letter-spacing: 1.5px; text-transform: uppercase; }
  .grand-amount { font-size: 14pt; font-weight: bold; }
  .payment-section { margin-top: 22px; padding-top: 16px; border-top: 1px solid var(--color-bg-stripe); }
  .payment-title { font-size: 8pt; font-weight: bold; color: var(--color-muted); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 8px; }
  .payment-terms-label { font-size: 9pt; color: var(--color-text); background: var(--color-bg-soft); padding: 7px 12px; border-left: 3px solid var(--color-border); }
  table.payment-table { width: 100%; border-collapse: collapse; font-size: 8.5pt; margin-top: 6px; }
  table.payment-table th { background: var(--color-bg-stripe); color: var(--color-primary-dark); padding: 6px 10px; text-align: left; border: 1px solid #ccd; font-weight: bold; }
  table.payment-table td { padding: 6px 10px; border: 1px solid #dde; }
  table.payment-table td.right { text-align: right; }

  /* ── Aceptación ──────────────────────────── */
  .acceptance { page-break-before: always; }
  .acceptance-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; margin-top: 24px; }
  .acceptance-party .party-title { font-size: 9.5pt; font-weight: bold; color: var(--color-primary-dark); margin-bottom: 8px; border-bottom: 2px solid var(--color-primary-dark); padding-bottom: 4px; }
  .sig-line { border-bottom: 1px solid var(--color-text); height: 44px; margin: 20px 0 8px; }
  .sig-label { font-size: 8pt; color: var(--color-text-secondary); margin-bottom: 5px; }
</style>

<div class="proposal">

{# ─── 1. PORTADA ────────────────────────────────── #}
{# Logo URL: uses frappe.utils.get_url to convert relative path to absolute URL #}
{# so wkhtmltopdf (headless) can resolve it. Falls back to company name text.   #}
{%- set logo_url = get_logo_url(company.company_logo) if (company and company.company_logo) else None -%}
<div class="cover">
  <div class="cover-band"></div>

  <div class="cover-header">
    <div class="cover-logo-area">
      {% if logo_url %}
      <img src="{{ logo_url }}" alt="{{ company.company_name if company else '' }}">
      {% else %}
      <div class="company-name-fallback">{{ company.company_name if company else '' }}</div>
      {% endif %}
    </div>
    <div class="cover-badge">PROPUESTA</div>
  </div>

  <div class="cover-title-block">
    <div class="cover-main-title">Propuesta Comercial</div>
    {% if doc.proposal_title %}
    <div class="cover-subtitle">{{ fix_lig(doc.proposal_title) }}</div>
    {% endif %}
  </div>

  <div class="cover-parties">
    <div class="cover-client">
      <div class="party-label">Preparado para</div>
      <div class="client-name">{{ doc.customer_name or doc.party_name or '—' }}</div>
      <div class="cover-meta-grid">
        <div class="cover-meta-row"><span class="meta-key">Folio</span><span class="meta-val">{{ doc.name }}</span></div>
        <div class="cover-meta-row"><span class="meta-key">Fecha</span><span class="meta-val">{{ frappe.utils.formatdate(doc.transaction_date) }}</span></div>
        <div class="cover-meta-row"><span class="meta-key">Vigencia</span><span class="meta-val">{{ frappe.utils.formatdate(doc.valid_till) if doc.valid_till else '—' }}</span></div>
        <div class="cover-meta-row"><span class="meta-key">Moneda</span><span class="meta-val">{{ doc.currency }}</span></div>
      </div>
    </div>
    <div class="cover-issuer">
      <div class="party-label">Preparado por</div>
      <div class="issuer-name">{{ company.company_name if company else '' }}</div>
      {% if owner_name or owner_email %}
      <div class="issuer-detail">
        {% if owner_name %}{{ owner_name }}{% endif %}
        {% if owner_email %}<br>{{ owner_email }}{% endif %}
      </div>
      {% endif %}
    </div>
  </div>

  <div class="confidential-banner">Confidencial — Solo para uso del destinatario</div>
</div>

{# ─── 2. RESUMEN EJECUTIVO ──────────────────────────────────── #}
{# Snapshot path or live path. Content rendered with render_section_content #}
{# (resolves Jinja vars at render time from frozen raw content).            #}
{%- if _is_frozen and not use_snapshot -%}
<div style="background:#fff3cd;border:1px solid #ffc107;padding:8px 12px;font-size:8pt;color:#856404;margin-bottom:16px">
  ⚠️ Esta propuesta está en estado congelado pero no tiene contenido fijo registrado. El PDF puede no reflejar el documento original enviado a revisión.
</div>
{%- endif -%}
{%- if use_snapshot -%}
  {%- if snap_exec -%}
    {%- set _ei = snap_exec[0] -%}
    {%- if _ei.content -%}
    <div class="exec-summary">
      <div class="exec-summary-title">{{ fix_lig(_ei.title) }}</div>
      <div class="exec-summary-subtitle">Resumen Ejecutivo</div>
      <div class="exec-content">{{ render_section_content(_ei.content, doc) | safe }}</div>
      <div class="exec-data-grid">
        <div class="exec-card"><div class="ec-label">Folio</div><div class="ec-value">{{ doc.name }}</div></div>
        <div class="exec-card"><div class="ec-label">Fecha</div><div class="ec-value">{{ frappe.utils.formatdate(doc.transaction_date) }}</div></div>
        <div class="exec-card"><div class="ec-label">Vigencia</div><div class="ec-value">{{ frappe.utils.formatdate(doc.valid_till) if doc.valid_till else '—' }}</div></div>
        <div class="exec-card"><div class="ec-label">Moneda</div><div class="ec-value">{{ doc.currency }}</div></div>
        <div class="exec-card"><div class="ec-label">Inversión total</div><div class="ec-value">{{ '{:,.0f}'.format(doc.grand_total) }} {{ doc.currency }}</div></div>
        {% if total_est_h.v %}<div class="exec-card"><div class="ec-label">Horas estimadas</div><div class="ec-value">{{ '{:g}'.format(total_est_h.v) }}h</div></div>{% endif %}
      </div>
    </div>
    {%- endif -%}
  {%- endif -%}
{%- elif exec_sections -%}
  {%- set exec_row = exec_sections[0] -%}
  {%- set ps_exec = frappe.get_doc('Proposal Section', exec_row.proposal_section) -%}
  {%- set exec_title = exec_row.custom_title or ps_exec.title or ps_exec.section_name -%}
  {%- set exec_content = exec_row.custom_content if exec_row.use_custom_content else ps_exec.content -%}
  {%- if ps_exec.enabled and exec_content -%}
  <div class="exec-summary">
    <div class="exec-summary-title">{{ fix_lig(exec_title) }}</div>
    <div class="exec-summary-subtitle">Resumen Ejecutivo</div>
    <div class="exec-content">{{ render_section_content(exec_content, doc) | safe }}</div>
    <div class="exec-data-grid">
      <div class="exec-card"><div class="ec-label">Folio</div><div class="ec-value">{{ doc.name }}</div></div>
      <div class="exec-card"><div class="ec-label">Fecha</div><div class="ec-value">{{ frappe.utils.formatdate(doc.transaction_date) }}</div></div>
      <div class="exec-card"><div class="ec-label">Vigencia</div><div class="ec-value">{{ frappe.utils.formatdate(doc.valid_till) if doc.valid_till else '—' }}</div></div>
      <div class="exec-card"><div class="ec-label">Moneda</div><div class="ec-value">{{ doc.currency }}</div></div>
      <div class="exec-card"><div class="ec-label">Inversión total</div><div class="ec-value">{{ '{:,.0f}'.format(doc.grand_total) }} {{ doc.currency }}</div></div>
      {% if total_est_h.v %}<div class="exec-card"><div class="ec-label">Horas estimadas</div><div class="ec-value">{{ '{:g}'.format(total_est_h.v) }}h</div></div>{% endif %}
    </div>
  </div>
  {%- endif -%}
{%- endif -%}

{# ─── 3. ÍNDICE ─────────────────────────────────── #}
{%- set toc_items = [] -%}
{%- if use_snapshot -%}
  {%- for item in snap_body -%}
    {%- set _ = toc_items.append(item.title) -%}
  {%- endfor -%}
{%- else -%}
  {%- for row in body_sections -%}
    {%- set ps_t = frappe.get_doc('Proposal Section', row.proposal_section) -%}
    {%- if ps_t.enabled -%}
      {%- set _ = toc_items.append(row.custom_title or ps_t.title or ps_t.section_name) -%}
    {%- endif -%}
  {%- endfor -%}
{%- endif -%}
{%- if scope_rows %}{%- set _ = toc_items.append('Plan de Trabajo') -%}{%- endif -%}
{%- set _has_deliverables = scope_rows | selectattr('deliverable') | list | length > 0 -%}
{%- if _has_deliverables %}{%- set _ = toc_items.append('Entregables') -%}{%- endif -%}
{%- if doc.items %}{%- set _ = toc_items.append('Inversión') -%}{%- endif -%}
{%- for row in late_sections -%}
  {%- set ps_t = frappe.get_doc('Proposal Section', row.proposal_section) -%}
  {%- if ps_t.enabled -%}
    {%- set _ = toc_items.append(row.custom_title or ps_t.title or ps_t.section_name) -%}
  {%- endif -%}
{%- endfor -%}
{%- set _ = toc_items.append('Aprobación de Propuesta') -%}
{% if toc_items %}
<div class="toc-block">
  <div class="toc-title">Contenido</div>
  <ul class="toc-list">
    {% for item in toc_items %}
    <li><span class="toc-num">{{ loop.index }}.</span> {{ fix_lig(item) }}</li>
    {% endfor %}
  </ul>
</div>
{% endif %}

{# ─── 4. SECCIONES NARRATIVAS ───────────────────────────────── #}
{# Snapshot path: use frozen content. Live path: read from catalog.        #}
{%- if use_snapshot -%}
  {%- for item in snap_body | rejectattr("sequence", "ge", 500) | list -%}
    {%- if item.content -%}
  <div class="section">
    <h2 class="section-title">{{ fix_lig(item.title) }}</h2>
    <div class="section-content">{{ render_section_content(item.content, doc) | safe }}</div>
  </div>
    {%- endif -%}
  {%- endfor -%}
{%- else -%}
  {% for row in body_sections %}
    {%- set ps = frappe.get_doc('Proposal Section', row.proposal_section) -%}
    {%- set s_title = row.custom_title or ps.title or ps.section_name -%}
    {%- set s_content = row.custom_content if row.use_custom_content else ps.content -%}
    {% if ps.enabled and s_content %}
  <div class="section">
    <h2 class="section-title">{{ fix_lig(s_title) }}</h2>
    <div class="section-content">{{ render_section_content(s_content, doc) | safe }}</div>
  </div>
    {% endif %}
  {% endfor %}
{%- endif -%}

{# ─── 5. PLAN DE TRABAJO ───────────────────────────── #}
{% if scope_rows %}
<div class="section">
  <h2 class="section-title">Plan de Trabajo</h2>
  {%- set sorted_rows = scope_rows | sort(attribute='idx') | sort(attribute='sequence') | list -%}
  {%- set phases = [] -%}
  {%- for item in sorted_rows -%}
    {%- if item.phase not in phases -%}{%- set _ = phases.append(item.phase) -%}{%- endif -%}
  {%- endfor -%}
  <table class="deploy-table">
    <thead>
      <tr>
        <th>Actividad</th>
        {% if has_designation %}<th style="width:14%">Perfil</th>{% endif %}
        {% if has_activity %}<th style="width:13%">Tipo</th>{% endif %}
        <th class="right" style="width:8%">Horas</th>
        <th class="right" style="width:7%">Días</th>
      </tr>
    </thead>
    <tbody>
      {%- set total_h = namespace(value=0) -%}
      {% for phase in phases %}
        {%- set phase_items = sorted_rows | selectattr('phase', 'equalto', phase) | list -%}
        {%- set phase_h = namespace(value=0) -%}
        <tr class="phase-row">
          <td colspan="{{ 3 + (1 if has_designation else 0) + (1 if has_activity else 0) }}">{{ fix_lig(phase or 'Sin fase') }}</td>
        </tr>
        {% for item in phase_items %}
          {%- set h = (item.estimated_hours or 0) | float -%}
          {%- set phase_h.value = phase_h.value + h -%}
          <tr>
            <td class="task-cell">
              <strong>{{ fix_lig(item.title or item.code) }}</strong>
              {% if item.description %}<div class="task-desc">{{ item.description | striptags | truncate(200) }}</div>{% endif %}
            </td>
            {% if has_designation %}<td>{{ item.designation or '' }}</td>{% endif %}
            {% if has_activity %}<td>{{ item.activity_type or '' }}</td>{% endif %}
            <td class="right">{{ '{:g}'.format(h) if h else '' }}</td>
            <td class="right">{{ '{:.2f}'.format(h/8) if h else '' }}</td>
          </tr>
        {% endfor %}
        {%- set total_h.value = total_h.value + phase_h.value -%}
        <tr class="phase-total">
          <td colspan="{{ 1 + (1 if has_designation else 0) + (1 if has_activity else 0) }}" class="right"><em>Total {{ fix_lig(phase or 'Sin fase') }}</em></td>
          <td class="right"><em>{{ '{:g}'.format(phase_h.value) }}h</em></td>
          <td class="right"><em>{{ '{:.2f}'.format(phase_h.value/8) }}d</em></td>
        </tr>
      {% endfor %}
    </tbody>
    <tfoot>
      <tr>
        <td colspan="{{ 1 + (1 if has_designation else 0) + (1 if has_activity else 0) }}" class="right">TOTAL PROYECTO</td>
        <td class="right">{{ '{:g}'.format(total_h.value) }}h</td>
        <td class="right">{{ '{:.2f}'.format(total_h.value/8) }}d</td>
      </tr>
    </tfoot>
  </table>
</div>
{% endif %}

{# ─── 6. ENTREGABLES ──────────────────────────────── #}
{%- set items_with_deliverable = scope_rows | selectattr('deliverable') | list -%}
{% if items_with_deliverable %}
<div class="section">
  <h2 class="section-title">Entregables</h2>
  {% for item in items_with_deliverable | sort(attribute='idx') | sort(attribute='sequence') %}
  <div class="deliverable-item">
    <div class="deliverable-title">{{ fix_lig(item.title or item.code) }}</div>
    <div class="deliverable-body">{{ render_section_content(item.deliverable, doc) | safe }}</div>
  </div>
  {% endfor %}
</div>
{% endif %}

{# ─── 7. INVERSIÓN ────────────────────────────────── #}
{% if doc.items %}
<div class="section">
  <h2 class="section-title">Inversión</h2>
  <table class="items-table">
    <thead>
      <tr>
        <th>Concepto</th>
        <th class="right" style="width:9%">Cant.</th>
        <th class="right" style="width:17%">Precio Unit. {{ doc.currency }}</th>
        <th class="right" style="width:17%">Subtotal {{ doc.currency }}</th>
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
      <tr>
        <td>
          <div class="item-name">{{ fix_lig(item.item_name) }}</div>
          {% if item.description %}<div class="item-desc">{{ item.description | striptags | truncate(160) }}</div>{% endif %}
        </td>
        <td class="right">{{ '{:g}'.format(item.qty) }}</td>
        <td class="right">{{ '{:,.2f}'.format(item.rate) }}</td>
        <td class="right">{{ '{:,.2f}'.format(item.net_amount) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="totals-block">
    {%- if doc.net_total != doc.grand_total or doc.discount_amount or doc.total_taxes_and_charges -%}
    <div class="totals-subtotals">
      <div class="totals-inner">
        <div class="totals-row"><span>Subtotal</span><span>{{ '{:,.2f}'.format(doc.net_total) }}</span></div>
        {% if doc.discount_amount %}
        <div class="totals-row"><span>Descuento</span><span>&minus;{{ '{:,.2f}'.format(doc.discount_amount) }}</span></div>
        {% endif %}
        {% if doc.total_taxes_and_charges %}
        <div class="totals-row"><span>Impuestos</span><span>{{ '{:,.2f}'.format(doc.total_taxes_and_charges) }}</span></div>
        {% endif %}
      </div>
    </div>
    {%- endif -%}
    <div class="totals-grand">
      <span class="grand-label">Total {{ doc.currency }}</span>
      <span class="grand-amount">{{ '{:,.2f}'.format(doc.grand_total) }}</span>
    </div>
  </div>

  {% if doc.payment_terms_template or doc.payment_schedule %}
  <div class="payment-section">
    <div class="payment-title">Condiciones de pago</div>
    {% if doc.payment_terms_template and not doc.payment_schedule %}
    <div class="payment-terms-label">{{ doc.payment_terms_template }}</div>
    {% endif %}
    {% if doc.payment_schedule %}
    <table class="payment-table">
      <thead>
        <tr>
          <th>Concepto</th>
          <th class="right">Monto {{ doc.currency }}</th>
          <th class="right">Fecha</th>
        </tr>
      </thead>
      <tbody>
        {% for ps in doc.payment_schedule %}
        <tr>
          <td>{{ ps.payment_term or doc.payment_terms_template or '—' }}</td>
          <td class="right">{{ '{:,.2f}'.format(ps.payment_amount) }}</td>
          <td class="right">{{ frappe.utils.formatdate(ps.due_date) if ps.due_date else '—' }}</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
    {% endif %}
  </div>
  {% endif %}
</div>
{% endif %}

{# ─── 8. SECCIONES LEGALES / COMERCIALES (sequence >= 500) ─── #}
{%- if use_snapshot -%}
  {%- for item in snap_body | selectattr("sequence", "ge", 500) | list -%}
    {%- if item.content -%}
  <div class="section">
    <h2 class="section-title">{{ fix_lig(item.title) }}</h2>
    <div class="section-content">{{ render_section_content(item.content, doc) | safe }}</div>
  </div>
    {%- endif -%}
  {%- endfor -%}
{%- elif doc.proposal_template and late_sections is defined and late_sections -%}
  {% for row in late_sections %}
    {%- set ps = frappe.get_doc('Proposal Section', row.proposal_section) -%}
    {%- set s_title = row.custom_title or ps.title or ps.section_name -%}
    {%- set s_content = row.custom_content if row.use_custom_content else ps.content -%}
    {% if ps.enabled and s_content %}
  <div class="section">
    <h2 class="section-title">{{ fix_lig(s_title) }}</h2>
    <div class="section-content">{{ render_section_content(s_content, doc) | safe }}</div>
  </div>
    {% endif %}
  {% endfor %}
{%- endif -%}

{# ─── CONDICIONES COMERCIALES (doc.terms, solo si no hay late_sections) ─ #}
{% if doc.terms and not (late_sections is defined and late_sections) %}
<div class="section">
  <h2 class="section-title">Condiciones Comerciales</h2>
  <div class="section-content" style="font-size:9pt">{{ fix_lig(doc.terms) }}</div>
</div>
{% endif %}

{# ─── 9. BLOQUE DE ACEPTACIÓN ─────────────────────── #}
<div class="section acceptance">
  <h2 class="section-title">Aceptación de Propuesta</h2>
  <p style="font-size:9pt;color:#555;margin-bottom:16px">La firma del presente documento indica la aceptación formal de los términos, alcance e inversión descritos en esta propuesta.</p>
  <div class="acceptance-grid">
    <div class="acceptance-party">
      <div class="party-title">Cliente</div>
      <div class="sig-line"></div>
      <div class="sig-label">Nombre: {{ doc.customer_name or doc.party_name or '______________________________' }}</div>
      <div class="sig-label">Cargo: ______________________________</div>
      <div class="sig-label">Fecha: ______________________________</div>
    </div>
    <div class="acceptance-party">
      <div class="party-title">{{ company.company_name if company else 'Proveedor' }}</div>
      <div class="sig-line"></div>
      <div class="sig-label">Nombre: {{ owner_name or '______________________________' }}</div>
      <div class="sig-label">Cargo: ______________________________</div>
      <div class="sig-label">Fecha: ______________________________</div>
    </div>
  </div>
</div>

</div>
